"""Generate deterministic vector PDF fixtures for the test suite.

Run from the repo root:
    uv run python scripts/generate_fixtures.py

Outputs are written to tests/fixtures/pdfs/. They are byte-stable across
runs (we set creation_date=0 so the PDF embeds no timestamp).
"""

from __future__ import annotations

from datetime import UTC, datetime
from pathlib import Path

from fpdf import FPDF

# Fixed timestamp so generated bytes are stable across runs.
EPOCH = datetime(2026, 1, 1, tzinfo=UTC)

REPO_ROOT = Path(__file__).resolve().parents[1]
OUT_DIR = REPO_ROOT / "tests" / "fixtures" / "pdfs"


def _new_pdf(width_mm: float, height_mm: float) -> FPDF:
    pdf = FPDF(unit="mm", format=(width_mm, height_mm))
    pdf.set_creation_date(EPOCH)  # deterministic — same timestamp every run
    pdf.add_page()
    return pdf


def make_sample_vector() -> Path:
    """50×60mm canvas, single black-stroke rectangle. Used by PdfiumReader tests."""
    pdf = _new_pdf(50.0, 60.0)
    pdf.set_draw_color(0, 0, 0)
    pdf.set_line_width(0.5)
    pdf.rect(5, 5, 40, 50)
    out = OUT_DIR / "sample-vector.pdf"
    pdf.output(str(out))
    return out


def make_wallet_demo() -> Path:
    """95×110mm canvas (matches Wallet-Small SKU), black outline + an engrave fill."""
    pdf = _new_pdf(95.0, 110.0)

    # Cut outline (palette layer 00, black)
    pdf.set_draw_color(0, 0, 0)
    pdf.set_line_width(0.5)
    pdf.rect(5, 5, 85, 100)

    # Engrave area (palette layer 01, blue) — stroked only for MVP simplicity
    pdf.set_draw_color(0, 0, 255)
    pdf.set_line_width(0.5)
    pdf.rect(20, 20, 55, 30)

    out = OUT_DIR / "LB-WALLET-LEATHER-S__demo.pdf"
    pdf.output(str(out))
    return out


def make_wallet_showcase() -> Path:
    """A richer demo design for client showcases.

    95×110mm Wallet-Small canvas with:
      • Black cut outline (rounded-rectangle approximated with chamfered corners)
      • Blue engrave: decorative cross + corner ticks + diagonal accent lines
    """
    pdf = _new_pdf(95.0, 110.0)

    # ── Cut outline (layer 00 / black) ─────────────────────────────────────
    pdf.set_draw_color(0, 0, 0)
    pdf.set_line_width(0.5)
    # Chamfered rectangle: 8 segments instead of 4 for visual interest
    c = 4.0  # chamfer size
    x0, y0, x1, y1 = 6.0, 6.0, 89.0, 104.0
    pts = [
        (x0 + c, y0),
        (x1 - c, y0),
        (x1, y0 + c),
        (x1, y1 - c),
        (x1 - c, y1),
        (x0 + c, y1),
        (x0, y1 - c),
        (x0, y0 + c),
        (x0 + c, y0),  # close
    ]
    for (sx, sy), (ex, ey) in zip(pts, pts[1:], strict=False):
        pdf.line(sx, sy, ex, ey)

    # ── Engrave: a centred plus/cross ──────────────────────────────────────
    pdf.set_draw_color(0, 0, 255)
    pdf.set_line_width(0.4)
    cx, cy = 47.5, 55.0  # canvas centre
    arm = 14.0  # arm length each side
    # Horizontal bar
    pdf.line(cx - arm, cy, cx + arm, cy)
    pdf.line(cx - arm, cy - 3, cx + arm, cy - 3)
    pdf.line(cx - arm, cy + 3, cx + arm, cy + 3)
    # Vertical bar
    pdf.line(cx, cy - arm, cx, cy + arm)
    pdf.line(cx - 3, cy - arm, cx - 3, cy + arm)
    pdf.line(cx + 3, cy - arm, cx + 3, cy + arm)

    # ── Engrave: corner ticks (4 small L-shapes near each outline corner) ──
    tick = 5.0
    inset = 12.0
    for corner_x, corner_y, dx, dy in (
        (x0 + inset, y0 + inset, +1, +1),  # top-left
        (x1 - inset, y0 + inset, -1, +1),  # top-right
        (x1 - inset, y1 - inset, -1, -1),  # bottom-right
        (x0 + inset, y1 - inset, +1, -1),  # bottom-left
    ):
        pdf.line(corner_x, corner_y, corner_x + tick * dx, corner_y)
        pdf.line(corner_x, corner_y, corner_x, corner_y + tick * dy)

    # ── Engrave: diagonal accent lines bottom ──────────────────────────────
    for i in range(5):
        offset = i * 4
        pdf.line(20 + offset, 88, 40 + offset, 95)

    out = OUT_DIR / "LB-WALLET-LEATHER-S__showcase.pdf"
    pdf.output(str(out))
    return out


def _make_engraving_pdf(
    out_path: Path, width_mm: float, height_mm: float, decoration: str
) -> Path:
    """Small engraving-mock PDF: black cut outline + a per-item vector
    decoration. Vector-only (no fonts / no `pdf.text`) so LightBurn's
    importer picks everything up — and so the design PDF carries the
    shape only, not the customization text (which is typed into LightBurn
    based on the order's customization field at engrave time).
    """
    pdf = _new_pdf(width_mm, height_mm)
    pdf.set_draw_color(0, 0, 0)
    pdf.set_line_width(0.5)
    pdf.rect(2, 2, width_mm - 4, height_mm - 4)  # black cut outline

    cx, cy = width_mm / 2, height_mm / 2
    pdf.set_draw_color(0, 0, 255)
    pdf.set_line_width(0.4)

    if decoration == "circle":
        r = min(width_mm, height_mm) / 8
        pdf.ellipse(cx - r, cy - r, r * 2, r * 2)
    elif decoration == "triangle":
        side = min(width_mm, height_mm) / 4
        h = side * 0.866
        pdf.line(cx, cy - h / 2, cx - side / 2, cy + h / 2)
        pdf.line(cx - side / 2, cy + h / 2, cx + side / 2, cy + h / 2)
        pdf.line(cx + side / 2, cy + h / 2, cx, cy - h / 2)
    elif decoration == "diamond":
        d = min(width_mm, height_mm) / 5
        pdf.line(cx, cy - d, cx + d, cy)
        pdf.line(cx + d, cy, cx, cy + d)
        pdf.line(cx, cy + d, cx - d, cy)
        pdf.line(cx - d, cy, cx, cy - d)
    elif decoration == "three_bars":
        bar_h = min(width_mm, height_mm) / 3
        spacing = min(width_mm, height_mm) / 8
        for x in (cx - spacing, cx, cx + spacing):
            pdf.line(x, cy - bar_h / 2, x, cy + bar_h / 2)

    pdf.output(str(out_path))
    return out_path


def make_seed_orders() -> list[Path]:
    """Generate one PDF per side referenced in src/lbb/web/assets/seed-orders/orders.json.

    Filenames match the pdf_path values in that JSON exactly so the web UI can
    resolve them without any path translation.
    """
    seed_dir = REPO_ROOT / "src" / "lbb" / "web" / "assets" / "seed-orders"
    seed_dir.mkdir(parents=True, exist_ok=True)
    written: list[Path] = []
    items = [
        # name,                                  width,  height, decoration
        ("306-2309613-0964321-A-Front.pdf", 40.0, 60.0, "diamond"),
        ("306-2309613-0964321-A-Back.pdf",  40.0, 60.0, "three_bars"),
        ("306-2309613-0964321-B-Front.pdf", 50.0, 20.0, "circle"),
        ("304-9988776-1122334-A-Front.pdf", 50.0, 30.0, "triangle"),
    ]
    for name, w, h, deco in items:
        written.append(_make_engraving_pdf(seed_dir / name, w, h, deco))
    return written


def make_seed_labels() -> list[Path]:
    """Generate one label PDF per order into seed-orders/labels/.

    Filenames match the label.pdf_path values in orders.json. PDFs are
    vector-only (no text/fonts) so bytes stay deterministic across runs.
    """
    seed_dir = REPO_ROOT / "src" / "lbb" / "web" / "assets" / "seed-orders"
    labels_dir = seed_dir / "labels"
    labels_dir.mkdir(parents=True, exist_ok=True)
    written: list[Path] = []
    orders = [
        "306-2309613-0964321",
        "304-9988776-1122334",
    ]
    for order_number in orders:
        pdf = _new_pdf(100.0, 60.0)

        # Filled "barcode" background bar
        pdf.set_fill_color(0, 0, 0)
        pdf.rect(5, 10, 90, 18, style="F")

        # Thin vertical lines to suggest barcode stripes (vector-only)
        pdf.set_draw_color(255, 255, 255)
        pdf.set_line_width(0.3)
        for i in range(30):
            x = 7 + i * 2.8
            pdf.line(x, 10, x, 28)

        # Two decorative border rectangles (carrier / recipient zones)
        pdf.set_draw_color(0, 0, 0)
        pdf.set_line_width(0.4)
        pdf.rect(5, 32, 90, 10)   # carrier zone outline
        pdf.rect(5, 44, 90, 12)   # recipient zone outline

        out = labels_dir / f"{order_number}.pdf"
        pdf.output(str(out))
        written.append(out)
    return written


def make_curve_test() -> Path:
    """50×50mm canvas with one black-stroke ellipse. Used by Bezier-flatten tests
    — fpdf2's ellipse() emits the shape as four cubic Bezier curves, exactly the
    PDF segment type our extractor must flatten."""
    pdf = _new_pdf(50.0, 50.0)
    pdf.set_draw_color(0, 0, 0)
    pdf.set_line_width(0.5)
    pdf.ellipse(10, 10, 30, 30)
    out = OUT_DIR / "curve-test.pdf"
    pdf.output(str(out))
    return out


def main() -> None:
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    written: list[Path] = []
    for fn in (make_sample_vector, make_wallet_demo, make_wallet_showcase, make_curve_test):
        path = fn()
        written.append(path)
        print(f"  ✓ {path.relative_to(REPO_ROOT)} ({path.stat().st_size} bytes)")
    for path in make_seed_orders():
        written.append(path)
        print(f"  ✓ {path.relative_to(REPO_ROOT)} ({path.stat().st_size} bytes)")
    for path in make_seed_labels():
        written.append(path)
        print(f"  ✓ {path.relative_to(REPO_ROOT)} ({path.stat().st_size} bytes)")
    print(f"\nWrote {len(written)} fixture(s) to {OUT_DIR.relative_to(REPO_ROOT)}/")


if __name__ == "__main__":
    main()
